#include <libxml/parser.h>
#include <libxml/xpath.h>
#include <stdio.h>
#include <string.h>

int main() {
    const char* xml_data = 
        "<students>"
        "    <student>"
        "        <username>john_doe</username>"
        "        <password>jdpassword</password>"
        "        <name>John Doe</name>"
        "        <citizenship>USA</citizenship>"
        "        <age>25</age>"
        "    </student>"
        "    <student>"
        "        <username>bob_smith</username>"
        "        <password>bspassword</password>"
        "        <name>Bob Smith</name>"
        "        <citizenship>Canada</citizenship>"
        "        <age>22</age>"
        "    </student>"
        "</students>";

    xmlDocPtr doc = xmlParseMemory(xml_data, strlen(xml_data));
    if (!doc) {
        printf("Failed to parse XML\n");
        return 1;
    }

    xmlXPathContextPtr context = xmlXPathNewContext(doc);
    if (!context) {
        xmlFreeDoc(doc);
        printf("Failed to create XPath context\n");
        return 1;
    }

    char* xpath_expr = (char*)malloc(256);
    snprintf(xpath_expr, 256, "//student[username='john_doe' and password='jdpassword']");
    xmlXPathObjectPtr result = xmlXPathEvalExpression(xpath_expr, context);
    free(xpath_expr);

    if (!result || !result->nodesetval || result->nodesetval->nodeNr == 0) {
        printf("No matching student found\n");
        xmlXPathFreeObject(result);
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        return 1;
    }

    xmlNodePtr node = result->nodesetval->nodeTab[0];
    printf("Student found: %s, %s, %s\n", 
           (char*)xmlGetProp(node, (const char*)"name"),
           (char*)xmlGetProp(node, (const char*)"age"),
           (char*)xmlGetProp(node, (const char*)"citizenship"));

    xmlXPathFreeObject(result);
    xmlXPathFreeContext(context);
    xmlFreeDoc(doc);
    return 0;
}
